<?php
$appPage='notifications';$appTitle='Notifications';require __DIR__.'/../includes/customer_header.php';if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$pdo->prepare('UPDATE notifications SET read_at=UTC_TIMESTAMP() WHERE user_id=? AND read_at IS NULL')->execute([$customerId]);}$stmt=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50');$stmt->execute([$customerId]);$items=$stmt->fetchAll();
?><section class="panel"><div style="display:flex;justify-content:space-between;gap:20px"><h2>Activity updates</h2><form method="post"><?=csrfField()?><button class="button button-secondary">Mark all read</button></form></div><?php if(!$items):?><div class="empty">No notifications yet.</div><?php else:?><?php foreach($items as $item):?><article style="padding:16px 0;border-bottom:1px solid var(--valtoria-border)"><div style="display:flex;justify-content:space-between"><strong><?=e($item['title'])?></strong><?php if(!$item['read_at']):?><span class="badge">New</span><?php endif?></div><p><?=e($item['message'])?></p><small class="muted"><?=e($item['created_at'])?> UTC</small></article><?php endforeach?><?php endif?></section><?php require __DIR__.'/../includes/customer_footer.php';?>
